"use client";
import React, { useState } from "react";
/**
 * @component AiModelSelectorGlow
 * @source https://21st.dev
 * @author 21st.dev / Kokonut
 * @license MIT
 */
export function AiModelSelectorGlow({
  className = "",
}: {
  className?: string;
}) {
  const [active, setActive] = useState(false);

  return (
    <div className={`p-3 rounded-2xl border border-violet-500/40 bg-card/80 shadow-[0_0_15px_rgba(139,92,246,0.15)] ${className}`}>
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <span className="text-base">🧠</span>
          <div>
            <div className="text-xs font-bold text-foreground">Foundation Model Selector</div>
            <div className="text-[10px] text-muted-foreground">Interactive provider switcher with latency metrics</div>
          </div>
        </div>
        <button
          onClick={() => setActive(!active)}
          className={`px-2.5 py-1 rounded-lg text-xs font-semibold transition-all active:scale-95 ${
            active
              ? "bg-violet-600 text-white shadow-xs"
              : "bg-secondary text-secondary-foreground hover:bg-secondary/80"
          }`}
        >
          {active ? "Active ✓" : "Enable"}
        </button>
      </div>
    </div>
  );
}
export default AiModelSelectorGlow;
